function btn(text,action,cls='',ic='',attrs=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${text}</button>`;}
function link(text,to,cls='btn',ic=''){return `<a class="${cls}" href="#${to}">${ic?icon(ic):''}${text}</a>`;}
function toast(text,error=false){clearTimeout(toastTimer);$('#toast').className=`show${error?' error':''}`;$('#toast').textContent=text;toastTimer=setTimeout(()=>$('#toast').className='',4000);}
